   "sez": "italia",
   "titolo": "Il pg di Cassazione sull'ex Ilva: 'No allo stop, bilanciare salute e produzione'",
   "orig": "Il pg di Cassazione: 'No allo stop dell'ex Ilva, bilanciare salute e produzione'",
   "lead": "Il procuratore generale della Cassazione si è espresso contro la chiusura dell'ex Ilva, sottolineando la necessità di bilanciare la tutela della salute con le esigenze produttive. Durante l'udienza, il rappresentante della pubblica accusa ha evidenziato che, sebbene la pericolosità dell'amianto sia un dato indiscutibile, la Corte d'Appello di Milano si è limitata a desumere il pericolo senza accertarlo concretamente. In seguito alla discussione, la Suprema Corte si è riservata la decisione definitiva sulla vicenda giudiziaria. Lo riferisce ANSA.",
   "more": [
    "La questione dell'ex Ilva rappresenta da anni uno dei nodi più complessi del panorama industriale e ambientale italiano. Il bilanciamento tra la continuità produttiva di uno stabilimento strategico per la siderurgia nazionale e la salvaguardia della salute pubblica e dell'ambiente è al centro di numerosi contenziosi legali e dibattiti istituzionali."
   ],
