   "titolo": "Problemi al cloud di Google: down per Revolut e altri servizi digitali",
   "orig": "Problemi al cloud di Google, down di Revolut e altri servizi",
   "lead": "Un guasto tecnico alla piattaforma cloud di Google ha provocato il blocco di numerosi servizi digitali, tra cui i pagamenti tramite Revolut, colpendo milioni di utenti soprattutto in Gran Bretagna. L'interruzione improvvisa è stata attribuita a un problema di natura elettrica che ha compromesso il corretto funzionamento delle infrastrutture informatiche, generando disagi diffusi nell'accesso alle applicazioni e alle transazioni online. Lo riferisce ANSA.",
   "more": [
    "I servizi di cloud computing gestiti dai grandi giganti tecnologici costituiscono l'infrastruttura portante di gran parte dell'economia digitale moderna. Eventuali guasti o interruzioni in questi centri dati possono avere ripercussioni immediate a catena su banche, servizi di pagamento e piattaforme online in tutto il mondo."
   ],
