   "orig": "Kenya cult leader's children still being starved weeks before trial, son says",
   "lead": "Dan Mackenzie, figlio del leader di una setta in Kenya, ha dichiarato che i bambini continuano a subire la fame a settimane di distanza dall'avvio del procedimento giudiziario. L'uomo, che in un primo momento aveva difeso il padre dalle accuse, ha spiegato di aver cambiato posizione e di aver avvertito le autorità, sentendosi in dovere di denunciare persino la propria nonna per fermare le violenze. Lo riferisce BBC News.",
