   "titolo": "Due uomini nuovamente arrestati nel Regno Unito per un presunto complotto legato all'Iran alla base di RAF Fairford",
   "orig": "Police rearrest two men over RAF Fairford incident",
   "lead": "La polizia britannica ha nuovamente arrestato due uomini nell'ambito delle indagini su un episodio avvenuto il mese scorso presso la base aerea militare di RAF Fairford, in Inghilterra. Gli agenti dell'antiterrorismo hanno applicato per la prima volta le disposizioni del National Security Act, collegando formalmente la vicenda all'Iran e ipotizzando che i sospettati stessero operando per conto dei servizi di intelligence iraniani in relazione a una struttura utilizzata anche da forze statunitensi. Lo riferisce Financial Times.",
   "more": [
    "Le basi militari strategiche gestite congiuntamente da alleati occidentali rappresentano obiettivi particolarmente sensibili per attività di spionaggio internazionale e sabotaggio, portando i servizi di sicurezza a rafforzare la sorveglianza e l'applicazione delle normative antiterrorismo."
   ],
