   "sez": "mondo",
   "titolo": "Spagna, Junqueras commenta l'amnistia per il 'procés' e Feijóo conferma contatti con Vox per il Senato",
   "orig": "Última hora de la actualidad política, en directo | Junqueras, tras la aplicación de la amnistía: “La represión fue brutal e innecesaria, lo hicieron porque nos tenían miedo”",
   "lead": "In Spagna, il leader politico Oriol Junqueras ha commentato l'applicazione della legge di amnistia per i condannati legati al processo indipendentista catalano del 'procés', definendo la repressione subita come brutale e inutile e attribuendola alla paura delle istituzioni statali. Nel frattempo, il governo centrale celebra l'entrata in vigore del provvedimento, mentre il leader dell'opposizione Feijóo ha confermato l'esistenza di negoziati in corso con Vox per definire le liste della Camera Alta. Lo riferisce El País.",
   "more": [
    "La legge di amnistia per i fatti del 2017 in Catalogna rappresenta uno dei provvedimenti politici e giudiziari più controversi della recente storia spagnola, capace di polarizzare il dibattito tra le forze autonomiste e i partiti di opposizione conservatrice."
   ],
