   "sez": "salute",
   "titolo": "Vanessa Kerry nominata nuova inviata dell'OMS per la resilienza sanitaria",
   "orig": "Vanessa Kerry is the new WHO envoy for health resilience. What's on her to-do list?",
   "lead": "La dottoressa Vanessa Kerry ha assunto l'incarico di nuova inviata speciale dell'Organizzazione Mondiale della Sanità per la resilienza sanitaria globale. Riconosciuta figura di spicco nel campo della salute internazionale, la professionista ha commentato la nomina definendo la nuova responsabilità complessa ma non scoraggiante. Lo riferisce NPR.",
   "more": [
    "La resilienza sanitaria globale è la capacità dei sistemi sanitari nazionali e internazionali di prevenire, prepararsi e rispondere a emergenze pandemiche, crisi climatiche e shock epidemiologici, garantendo la continuità delle cure mediche di base."
   ],
