   "id": "z2e9b6c15",
   "sez": "musica",
   "titolo": "Il capolavoro di Stevie Wonder 'Songs in the Key of Life' compie 50 anni e si rinnova",
   "orig": "Stevie Wonder's 'Songs in the Key of Life' turns 50 -- and gets a refresh",
   "lead": "In occasione del cinquantesimo anniversario del celebre album di Stevie Wonder 'Songs in the Key of Life', l'artista ha pubblicato un EP speciale contenente quattro brani inediti e registrazioni storiche mai ascoltate prima. L'iniziativa celebra una delle opere musicali più influenti della storia della musica soul e pop, capace di evocare forti emozioni a distanza di mezzo secolo dal suo debutto. Lo riferisce NPR – Musica.",
   "more": [
    "Gli album storici della musica pop e R&B degli anni Sessanta e Settanta continuano a influenzare profondamente gli artisti contemporanei; le riedizioni celebrative con materiale inedito offrono agli appassionati l'opportunità di riscoprire i processi creativi di grandi maestri della discografia."
   ],
