   "id": "z7fe09118",
   "sez": "mondo",
   "titolo": "L'Isola di Jersey estende la protezione marina al 21% delle proprie acque territoriali",
   "orig": "Isle of Jersey Expands Marine Protections to Cover 21% of Territorial Waters",
   "lead": "Il governo autonomo dell'Isola di Jersey ha annunciato l'estensione delle aree marine protette, portando la superficie interdetta alla pesca a strascico e ad altre pratiche di sfruttamento dannoso al 21,7% delle proprie acque territoriali. Le nuove normative ambientali, entrate in vigore a settembre, mirano a salvaguardare gli habitat marini più vulnerabili e biologicamente preziosi che circondano il territorio britannico insulare. Lo riferisce Good News Network.",
   "more": [
    "La protezione degli ecosistemi marini costieri mediante l'istituzione di aree interdette alla pesca intensiva rappresenta uno strumento fondamentale per la conservazione della biodiversità marina e il ripopolamento delle specie ittiche nei mari di tutto il mondo."
   ],
