   "id": "zdd653237",
   "sez": "tech",
   "titolo": "Cittadino pachistano arrestato a Lahore con l'accusa di aver truffato il servizio postale statunitense per 126 milioni di dollari",
   "orig": "Pakistani national accused of defrauding US Postal Service of $126m arrested in Lahore: NCCIA",
   "lead": "Le autorità investigative del Pakistan hanno arrestato a Lahore un cittadino di 33 anni originario di Khanewal, individuato come il principale sospettato in un'inchiesta transnazionale sulla vendita di francobolli postali contraffatti. Secondo quanto riferito dall'Ufficio del Procuratore degli Stati Uniti per il Distretto Meridionale della Florida, l'uomo gestiva un sito web non autorizzato attraverso il quale sono state smerciate oltre cinque milioni di etichette postali contraffatte degli Stati Uniti, causando frodi per un valore superiore a 126 milioni di dollari. Lo riferisce Dawn.",
   "more": [
    "I crimini informatici legati alla falsificazione di documenti cartacei ufficiali e di etichette postali digitali attraverso siti web illeciti rappresentano una sfida complessa per le agenzie di cybersecurity e le forze dell'ordine internazionali, che richiedono la stretta cooperazione giudiziaria tra diversi Paesi."
   ],
