   "id": "z58eca7e4",
   "sez": "ingegneria",
   "titolo": "Il padiglione naturalistico di Desai Chia Architecture ispirato al movimento dell'acqua",
   "orig": "Rippling water informs wildlife pavilion by Desai Chia Architecture",
   "lead": "Lo studio statunitense Desai Chia Architecture ha progettato il Chatham Pond Pavilion, una struttura immersa in una proprietà privata di ottanta acri nella zona rurale di Chatham, nello Stato di New York, concepita come stazione di osservazione della fauna selvatica. L'edificio, destinato a una coppia con figli adulti, è composto da forme geometriche basate su cerchi intersecati che traggono ispirazione visiva dai cerchi concentrici formati dall'acqua increspata dello stagno circostante. Lo riferisce Dezeen.",
   "more": [
    "L'architettura paesaggistica e la progettazione di strutture ecologiche integrate nella natura mirano a minimizzare l'impatto visivo sul territorio circostante, offrendo al contempo spazi funzionali per l'osservazione scientifica o contemplativa della biodiversità locale."
   ],
