   "titolo": "Allerta meteo e scuole chiuse in diversi comuni di Liguria e Campania",
   "orig": "Allerta meteo scuole chiuse mercoledì 21 ottobre: stop alle lezioni in diversi comuni di Liguria e Campania. IN AGGIORNAMENTO",
   "lead": "Il maltempo torna a colpire diverse zone d'Italia, spingendo le amministrazioni locali di numerosi comuni in Liguria e Campania a disporre la chiusura delle scuole di ogni ordine e grado per la giornata di mercoledì 21 ottobre. Le ordinanze di sospensione delle lezioni sono state adottate dai sindaci per prevenire rischi legati alle avverse condizioni meteorologiche e alle allerte diramate dalla Protezione Civile. Lo riferisce Orizzonte Scuola.",
   "more": [
    "I sindaci dispongono la chiusura degli istituti scolastici in base alle allerte meteo ufficiali diramate dai centri funzionali regionali di protezione civile, al fine di tutelare l'incolumità degli studenti ed evitare situazioni di pericolo durante gli spostamenti casa-scuola."
   ],
