   "sez": "economia",
   "titolo": "Il costo della vita resta la principale preoccupazione dei neozelandesi in vista delle elezioni",
   "orig": "Election '26: Cost of living continues to be NZers' top concern",
   "lead": "A meno di un mese dalle elezioni generali in Nuova Zelanda, le pressioni economiche quotidiane legate alle spese per alloggio, cibo e carburante continuano a rappresentare la principale preoccupazione per i cittadini. Nel frattempo, in Europa, l'aumento dei prezzi dei beni essenziali alimenta il malcontento e spinge la crescita dei partiti di estrema destra in vista delle consultazioni elettorali dell'anno prossimo in Paesi come Francia, Germania e Italia. Lo riferisce RNZ.",
   "more": [
    "L'aumento del costo della vita incide direttamente sul potere d'acquisto delle famiglie, generando tensioni sociali che spesso influenzano gli orientamenti politici degli elettori e favoriscono le forze politiche di opposizione o radicali durante le campagne elettorali."
   ],
