   "orig": "Il ristorante Unforgettable chiude e scoppia il caso dei voucher già pagati. La proprietà: “Riapriamo a novembre”",
   "lead": "Il ristorante Unforgettable, situato nel centro storico di Torino, ha interrotto la propria attività, sollevando polemiche e interrogativi tra i clienti in possesso di voucher prepagati non ancora utilizzati. La proprietà ha tuttavia annunciato che l'esercizio commerciale riaprirà i battenti nel mese di novembre. Lo riferisce Gambero Rosso.",
