   "lead": "Un violento incendio è divampato nella notte in un autosalone situato in via Prenestina a Roma, con l'intervento dei vigili del fuoco scattato poco prima delle quattro del mattino. Il rogo ha completamente distrutto nove automobili e un furgone parcheggiati nell'area commerciale. Lo riferisce Il Messaggero – Roma.",
