   "orig": "In California stanno scomparendo i vigneti: oltre 19mila ettari estirpati in un anno. Il vino non si vende più come prima",
   "lead": "Il settore vitivinicolo della California sta affrontando una fase di forte contrazione, culminata nell'estirpazione di oltre diciannove ettari di vigneti nel giro di dodici mesi. La diminuzione dei consumi e la discesa del prezzo delle uve stanno spingendo diversi produttori agricoli a convertire i terreni verso colture differenti. Lo riferisce Gambero Rosso.",
