   "lead": "L'adozione dell'intelligenza artificiale nelle imprese viene paragonata all'introduzione storica dell'elettricità: se nella fase iniziale l'attenzione era focalizzata sulla mera possibilità di utilizzo, la transizione verso un modello infrastrutturale sposta ora la priorità sulla gestione efficiente delle risorse e dei costi operativi. Lo riferisce MIT Technology Review.",
