   "sez": "salute",
   "titolo": "Cure oncologiche in Sudafrica: le lunghe trasferte dei pazienti verso Bloemfontein",
   "orig": "SA’S CANCER STORY (PART 4): The many long journeys for cancer treatment far from home",
   "lead": "L'accesso alle cure oncologiche in Sudafrica costringe molti pazienti a compiere viaggi lunghi ed estenuanti lontano dalle proprie comunità per ricevere assistenza medica specializzata. Un'inchiesta condotta da Daily Maverick e Spotlight racconta i sacrifici delle persone che da vaste aree dell'interno del Paese e oltre si recano a Bloemfontein per sottoporsi a terapie contro il cancro, affrontando complesse trafile tra strutture sanitarie e disagi logistici. Il reportage mette in luce le disuguaglianze geografiche e strutturali che ostacolano la continuità dei trattamenti per i malati oncologici. Lo riferisce Daily Maverick.",
   "more": [
    "Nei Paesi con sistemi sanitari a forte concentrazione urbana, la centralizzazione dei presidi oncologici crea gravi barriere per la popolazione rurale. La necessità di percorrere centinaia di chilometri per cicli di radioterapia o chemioterapia comporta costi elevati e ritardi diagnostici, aumentando il tasso di abbandono delle cure e peggiorando le percentuali di sopravvivenza complessiva."
   ],
