   "titolo": "Arte in distributore automatico al centro culturale Westrand di Dilbeek",
   "orig": "Kunst uit de automaat in CC Westrand in Dilbeek: \"Visitekaartje voor kunstenaars uit de regio\"",
   "lead": "A partire dal prossimo gennaio, il centro culturale Westrand di Dilbeek, in Belgio, ospiterà un distributore automatico dedicato alla vendita di piccole opere d'arte realizzate da artisti del territorio. L'iniziativa mira a promuovere la creatività locale attraverso pacchetti tascabili accessibili a tutti i visitatori della struttura. Il centro culturale ha avviato una selezione per raccogliere le creazioni degli artisti della regione che desiderano partecipare al progetto e distribuire i propri lavori tramite questo formato originale. Lo riferisce VRT NWS.",
   "more": [
    "L'idea dei distributori automatici di opere d'arte è nata per rendere la fruizione artistica immediata, democratica ed economica. Trasformando un apparecchio di uso quotidiano in una microgalleria, queste iniziative permettono al pubblico generico di avvicinarsi all'arte contemporanea e offrono agli emergenti un canale visibile e privo delle barriere tipiche del mercato tradizionale."
   ],
