   "titolo": "Confermata condanna da 383 milioni a Toshiba per i difetti alla centrale idroelettrica",
   "orig": "Judge Affirms $383M Verdict Against Toshiba America Energy Over Faulty Hydro Plant Upgrades",
   "lead": "Un giudice statunitense ha confermato una condanna da 383 milioni di dollari contro Toshiba America Energy per difetti e carenze ingegneristiche riscontrati nei lavori di ammodernamento di una centrale idroelettrica ad accumulo tramite pompaggio in Michigan. Il contenzioso scaturisce da un appalto dal valore di 560 milioni di dollari destinato al ripristino dell'impianto attivo da cinquant'anni. Le verifiche tecniche hanno rilevato lavorazioni non conformi agli standard e carenze progettuali che hanno compromesso il corretto funzionamento delle infrastrutture energetiche rinnovate. Lo riferisce Engineering News-Record.",
   "more": [
    "Le centrali idroelettriche ad accumulo pompato operano muovendo l'acqua tra due bacini posti a quote differenti, accumulando energia nei momenti di bassa domanda e rilasciandola durante i picchi. La riqualificazione di impianti con mezzo secolo di vita richiede rigorosi standard ingegneristici, poiché guasti alle turbine o errori costruttivi possono causare gravi perdite economiche e instabilità alla rete elettrica."
   ],
