   "id": "zd4d3d8f2",
   "sez": "musica",
   "titolo": "Accuse di plagio a Drake: l'autore Aviel Hirschfield diffonde una traccia contesa",
   "orig": "Did Drake Steal “Janice STFU”?",
   "lead": "L'autore musicale Aviel Hirschfield ha accusato il rapper canadese Drake di essersi appropriato del brano intitolato Janice STFU. Il compositore sostiene che una traccia di riferimento prodotta in precedenza costituisca la prova inconfutabile del plagio, diffondendo il materiale audio a sostegno della propria contestazione. La questione ha riaperto il dibattito sull'uso delle tracce guida e sulla tutela del diritto d'autore nell'industria discografica contemporanea, dove spesso le linee melodiche e i testi circolano tra diversi interpreti e produttori. Lo riferisce Pitchfork.",
   "more": [
    "Nel mercato musicale moderno, le 'reference track' o tracce guida sono registrazioni dimostrative create dagli autori per proporre una composizione a un cantante. Questa prassi operativa rende talvolta difficile tracciare l'attribuzione originale dei crediti e dei diritti patrimoniali, generando frequenti controversie legali quando accordi contrattuali o riconoscimenti formali non risultano definiti con chiarezza tra le parti coinvolte."
   ],
