   "titolo": "Campi Flegrei, 68 scosse e sollevamento stabile nel bollettino INGV",
   "orig": "Campi Flegrei, 68 scosse di terremoto e sollevamento del suolo di 10 mm al mese: nuovo bollettino INGV",
   "lead": "Il nuovo bollettino dell'Istituto Nazionale di Geofisica e Vulcanologia sui Campi Flegrei segnala una situazione priva di evoluzioni a breve termine, con il sollevamento del suolo che si mantiene stabile a circa dieci millimetri al mese. Nell'area sono state registrate sessantotto scosse sismiche, con una magnitudo massima pari a 2.5, mentre i parametri termici restano costanti a 173 gradi alla Solfatara e a 94 gradi a Pisciarelli. Dal 2025 il Rione Terra ha accumulato un innalzamento complessivo di 32,5 centimetri. Lo riferisce Geopop.",
   "more": [
    "I Campi Flegrei sono un'ampia caldera vulcanica situata a ovest di Napoli, nota per il fenomeno del bradisismo, ovvero il lento sollevamento o abbassamento del suolo generato dalla pressione dei gas e dei fluidi idrotermali sotterranei. La rete di monitoraggio geofisico rileva costantemente la sismicità e le deformazioni crostali per valutare l'attività vulcanica e garantire la sicurezza della popolazione locale."
   ],
