   "titolo": "Utili in crescita per l'uzbeka Hamkorbank e vendite record di diamanti in Botswana",
   "orig": "Uzbekistan’s Hamkorbank nine-month net profit up 16.8% to nearly $125M",
   "lead": "Nei primi nove mesi dell'anno, la banca uzbeka Hamkorbank ha conseguito un utile netto di quasi 125 milioni di dollari, registrando una crescita del 16,8% rispetto al periodo corrispondente. Sul fronte dei mercati delle materie prime, la compagnia diamantifera Okavango Diamond Company del Botswana ha totalizzato vendite all'asta spot per 3,3 miliardi di pula, pari a circa 240 milioni di dollari, grazie al collocamento di 1,31 milioni di carati di diamanti grezzi nel corso dei primi tre trimestri.",
   "more": [
    "I risultati finanziari dei primi nove mesi dell'anno offrono indicazioni significative sulla tenuta dei mercati bancari e dell'estrazione di materie prime. L'espansione creditizia sostiene lo sviluppo nelle economie emergenti dell'Asia centrale, mentre per nazioni africane come il Botswana l'esportazione di diamanti costituisce la principale voce di entrata fiscale e di riserve valutarie estere."
   ],
