   "titolo": "FCSB in ansia per Karlo Muhar: possibile frattura prima del derby con il Rapid",
   "orig": "Probleme pentru FCSB. Un titular este în pericol să rateze derby-ul cu Rapid: „S-ar putea să aibă fractură”",
   "lead": "La formazione romena della FCSB rischia di dover fare a meno del centrocampista titolare Karlo Muhar per l'atteso derby contro il Rapid Bucarest, in programma sabato sera all'Arena Națională. Il presidente del consiglio di amministrazione del club, Mihai Stoica, ha spiegato che il giocatore trentenne ha riportato un problema fisico di rilievo e che gli accertamenti medici temono la presenza di una frattura. L'eventuale assenza del mediano costituisce una pesante incognita tattica per la squadra in vista della sfida cittadina. Lo riferisce HotNews.",
   "more": [
    "Il derby tra la FCSB e il Rapid Bucarest rappresenta una delle rivalità sportive più sentite del calcio romeno, caratterizzata da un'intensa partecipazione di pubblico e da una forte pressione mediatica. L'assenza di titolari chiave nei ruoli mediani prima di sfide così delicate impone spesso modifiche agli equilibri tattici della squadra, influenzando la gestione del ritmo e della fase difensiva."
   ],
