   "id": "zf98a7bec",
   "sez": "salute",
   "titolo": "Allarme per la sanità israeliana: oltre 1.300 medici hanno lasciato il Paese in tre anni",
   "orig": "'Strategic threat': Israel faces healthcare brain drain as 1,369 doctors leave in three years",
   "lead": "Il sistema sanitario israeliano affronta una grave fuga di competenze mediche, definita una minaccia strategica dai vertici della sanità: sono 1.369 i medici che hanno lasciato il Paese nell'arco di tre anni. Un sondaggio condotto dalla Israeli Medical Association su trentadue ospedali e centri clinici ha rivelato un costante flusso migratorio di camici bianchi all'estero, accelerato negli ultimi quindici mesi successivi agli attacchi guidati da Hamas del 7 ottobre 2023 e alla guerra nella Striscia di Gaza. Le autorità sanitarie esprimono forte preoccupazione per la carenza di personale nei reparti specialistici. Lo riferisce Middle East Eye.",
   "more": [
    "La disponibilità di personale medico qualificato è un elemento essenziale per la resilienza e la tenuta dei servizi sanitari nazionali, soprattutto durante fasi prolungate di conflitto o di tensione geopolitica. L'emigrazione dei medici verso l'estero compromette la capacità ospedaliera, allunga le liste d'attesa e impoverisce la formazione delle nuove generazioni di specialisti nei centri di cura pubblici."
   ],
