   "id": "z8700b392",
   "sez": "musica",
   "titolo": "Diagnosi di cancro per Doug Dulgarian: cancellato il tour dei They Are Gutting a Body of Water",
   "orig": "They Are Gutting a Body of Water’s Doug Dulgarian Diagnosed With Cancer",
   "lead": "Il musicista Doug Dulgarian, leader della band They Are Gutting a Body of Water, ha ricevuto una diagnosi di cancro. In seguito alla comunicazione sulle proprie condizioni di salute, il gruppo ha annunciato la cancellazione della tournée in programma per consentire le cure del cantante. La formazione ha tuttavia confermato l'intenzione di mantenere le esibizioni previste per il mese di dicembre nelle città di New York e Filadelfia, subordinandole all'andamento del quadro clinico del musicista. Lo riferisce Pitchfork.",
   "more": [
    "Nel circuito della musica indipendente, la cancellazione di una tournée comporta sfide finanziarie e organizzative sia per le band sia per i club locali che ospitano i concerti. La gestione di gravi patologie richiede una sospensione immediata dei ritmi di viaggio e delle esibizioni dal vivo, spingendo spesso le comunità di artisti e appassionati a mobilitarsi per supportare i membri colpiti da malattie."
   ],
