   "id": "za69e6435",
   "sez": "spazio",
   "titolo": "Nuove pale per elicotteri marziani: la NASA studia voli più lunghi su Marte",
   "orig": "NASA experimental Mars helicopter blade designs target longer flights",
   "lead": "I ricercatori della NASA stanno sviluppando e testando nuovi profili di pale per i futuri elicotteri destinati a volare su Marte, con l'obiettivo di realizzare missioni scientifiche più lunghe, veloci e ad altitudini superiori. Attraverso simulazioni computazionali ad alta fedeltà ed esperimenti condotti all'interno di gallerie del vento, gli ingegneri aerospaziali stanno ridisegnando le eliche dei rotori per adattarle alla rarefatta atmosfera marziana. Questi studi sperimentali getteranno le basi ingegneristiche per la prossima generazione di veicoli aerei impiegati nell'esplorazione del pianeta rosso. Lo riferisce Phys.org – Spazio.",
   "more": [
    "Il volo atmosferico su Marte presenta sfide uniche a causa della densità dell'aria, che è inferiore all'uno per cento rispetto a quella terrestre. Per generare una portanza sufficiente a sollevare il velivolo, le pale dei rotori devono ruotare a velocità estremamente elevate e possedere forme aerodinamiche avanzate, capaci di superare le resistenze fluide in condizioni estreme."
   ],
