   "id": "zfe7932b7",
   "sez": "viaggi",
   "titolo": "Viaggi in Francia tra proteste e carovita: i consigli del New York Times ai turisti",
   "orig": "Heading to France? Amid Recent Unrest, Here’s What to Know",
   "lead": "Il quotidiano The New York Times ha diffuso indicazioni e consigli pratici per i viaggiatori diretti in Francia, alla luce dei recenti disordini e delle proteste scoppiate a Parigi e in altre città transalpine. Le mobilitazioni, animate dal malcontento per il rincaro del costo della vita e per le condizioni dell'istruzione pubblica, hanno generato tensioni urbane e potrebbero ripetersi nelle prossime settimane. La guida illustra le precauzioni raccomandate ai turisti per informarsi in anticipo, monitorare i trasporti locali ed evitare le zone maggiormente interessate dai cortei di protesta. Lo riferisce The New York Times – Viaggi.",
   "more": [
    "I viaggi internazionali richiedono una pianificazione attenta in presenza di agitazioni sindacali o manifestazioni di piazza nei Paesi di destinazione. Le interruzioni nei trasporti pubblici metropolitani e i blocchi stradali temporanei possono rallentare gli spostamenti verso aeroporti e monumenti, rendendo opportuno consultare con regolarità i canali di informazione consolare e le comunicazioni delle aziende di trasporto locali."
   ],
