   "id": "z58b7fd06",
   "sez": "economia",
   "titolo": "Manovra e fiscalità: le imposte bancarie per Messina e le scadenze del bollo auto",
   "orig": "Manovra, Messina: 'Non c'è solo un settore che deve pagare, dalle banche 25 miliardi di imposte'",
   "lead": "Nel dibattito sulla legge di bilancio italiana, il consigliere delegato di Intesa Sanpaolo Carlo Messina ha ribadito che il carico fiscale non deve concentrarsi su un unico settore, evidenziando che il comparto bancario contribuisce già con circa 25 miliardi di euro di imposte e ricordando il proprio favore verso un contributo straordinario concordato su base triennale. Sul versante della fiscalità automobilistica, Il Messaggero chiarisce le scadenze del bollo auto da versare entro dicembre, precisando che il pagamento resta obbligatorio anche per i periodi che si estendono nel nuovo anno e che i ritardi non comportano esenzioni.",
   "more": [
    "La predisposizione della manovra finanziaria vede costantemente il confronto tra governo e categorie economiche sulla reperibilità delle coperture di bilancio. I contributi straordinari richiesti agli istituti di credito e le entrate derivanti da imposte locali e regionali, come la tassa automobilistica, costituiscono voci rilevanti per finanziare la spesa pubblica e rispettare i vincoli europei di finanza statale."
   ],
