   "titolo": "Il Viking sfida l'Aston Villa: il tecnico carica la squadra prima del match",
   "orig": "Viking-treneren før Aston-Villa kampen: – Vi er her for å kjempe",
   "lead": "L'allenatore del club norvegese del Viking ha presentato la sfida calcistica contro la squadra inglese dell'Aston Villa, affermando con determinazione che la propria formazione scenderà in campo per lottare e dare il massimo. Il tecnico ha definito la gara contro il club di Premier League come una delle prove più impegnative e significative affrontate finora dalla squadra, assicurando che i calciatori sono pronti a fronteggiare l'elevato livello tecnico e agonistico degli avversari europei per cercare di compiere un'impresa sul terreno di gioco. Lo riferisce NRK.",
   "more": [
    "I confronti diretti tra club scandinavi e formazioni della Premier League rappresentano tradizionalmente sfide asimmetriche sul piano delle risorse economiche e del valore di mercato delle rose. Ciononostante, l'organizzazione tattica, la preparazione atletica e l'intensità agonistica consentono spesso alle squadre meno blasonate di colmare parzialmente il divario nelle competizioni a eliminazione o nei tornei internazionali."
   ],
