   "orig": "Paddy Power cuts 1,400 jobs and blames betting tax rises",
   "lead": "A Londra, la società Paddy Power ha annunciato il taglio di 1.400 posti di lavoro, motivando la decisione con l'incremento delle imposte applicate dal governo ai casinò online e alle scommesse sportive introdotto con la manovra di bilancio dell'anno precedente. La misura fiscale ha inciso in modo significativo sui costi operativi dell'azienda. Lo riferisce BBC News.",
