   "lead": "A Windhoek, l'Associazione dell'ospitalità della Namibia (HAN) ha reso noto che il tasso di occupazione delle strutture ricettive turistiche nel Paese ha raggiunto il 66,5% nel corso del terzo trimestre dell'anno, superando i livelli registrati nello stesso periodo dell'anno precedente e superando anche i dati del 2019, trainato in particolare dal segmento del turismo di lusso. Lo riferisce The Namibian.",
